[
  {
    "statement": "In studies from The Gambia, Guinea, Liberia, the Republic of Congo, Gabon, Tanzania, Senegal, Uganda, and South Africa, many chimpanzee and gorilla reintroductions reported majority survival for at least 9 months to 5 years.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589"
    ]
  },
  {
    "statement": "Population increases of reintroduced primates were documented in The Gambia and Tanzania.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589"
    ]
  },
  {
    "statement": "Several reintroduced chimpanzee groups showed majority survival over 2–5 years.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589"
    ]
  },
  {
    "statement": "In Malaysia and Indonesia, outcomes for orangutan reintroduction included majority survival.",
    "citations": [
      "1589",
      "1591",
      "1567",
      "1590"
    ]
  },
  {
    "statement": "Orangutan reintroduction outcomes in Malaysia and Indonesia included 98% survival upon release and all Sumatran orangutans surviving at least three months.",
    "citations": [
      "1589",
      "1591",
      "1567",
      "1590"
    ]
  },
  {
    "statement": "One long-term study in Malaysia recorded a decline in the reintroduced orangutan population after 33 years.",
    "citations": [
      "1589",
      "1591",
      "1567",
      "1590"
    ]
  },
  {
    "statement": "In Thailand and Vietnam, multiple studies on primate reintroduction reported population declines or very low survival.",
    "citations": [
      "1589",
      "1591",
      "1590",
      "1600"
    ]
  },
  {
    "statement": "A reintroduced primate population in Thailand or Vietnam declined over three years.",
    "citations": [
      "1589",
      "1591",
      "1590",
      "1600"
    ]
  },
  {
    "statement": "All reintroduced pygmy slow lorises in one study were assumed dead despite fostering.",
    "citations": [
      "1589",
      "1591",
      "1590",
      "1600"
    ]
  },
  {
    "statement": "In Brazil and French Guiana, several studies found only a minority of reintroduced primates survived from 15 weeks up to several years.",
    "citations": [
      "1567",
      "1591",
      "1600",
      "1590"
    ]
  },
  {
    "statement": "Most reintroduced golden lion tamarins in Brazil and French Guiana did not survive over 1–7 years.",
    "citations": [
      "1567",
      "1591",
      "1600",
      "1590"
    ]
  },
  {
    "statement": "In some primate reintroduction cases, Belize recorded population increases and majority short-term survival.",
    "citations": [
      "1567",
      "1591",
      "1600",
      "1590"
    ]
  },
  {
    "statement": "In Madagascar and India, persistence and survival of reintroduced primates were reported in several cases.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "Reintroduced primate populations in Madagascar have persisted for 4–55 years.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "A reintroduced primate population in India persisted for at least four years.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "Studies in Madagascar and India noted both majority and minority survival of reintroduced primates over months to years.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "Compiled evidence shows higher frequencies of majority survival and some population growth for reintroduced primates in several African country case studies.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589",
      "1600",
      "1595"
    ]
  },
  {
    "statement": "Case studies of primate reintroduction in Asian countries show mixed results, with both successes and notable failures.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589",
      "1600",
      "1595"
    ]
  },
  {
    "statement": "Case studies of primate reintroduction in American countries show mixed outcomes.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589",
      "1600",
      "1595"
    ]
  },
  {
    "statement": "Among American country case studies, Belize showed population increases for reintroduced primates, while Brazil and French Guiana often reported minority survival.",
    "citations": [
      "1567",
      "1590",
      "1591",
      "1589",
      "1600",
      "1595"
    ]
  }
]
